import React, { useEffect, useState } from "react";
import axios from "axios";

function QuizTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [courseId, setCourseId] = useState("");
  const [title, setTitle] = useState("");
  const [quizId, setQuizId] = useState(null);

  const [question, setQuestion] = useState("");
  const [options, setOptions] = useState({
    option1: "",
    option2: "",
    option3: "",
    option4: ""
  });
  const [correct, setCorrect] = useState("");

  // 🔥 Load courses
  useEffect(() => {
    axios.get("http://127.0.0.1:8000/courses")
      .then(res => setCourses(res.data.courses || []))
      .catch(err => console.error(err));
  }, []);

  // 🔥 Create Quiz
  const createQuiz = async () => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/create-quiz", {
        course_id: parseInt(courseId),
        teacher_id: parseInt(teacherId),
        title: title
      });

      setQuizId(res.data.quiz_id);
      alert("Quiz Created!");
    } catch (err) {
      console.error(err);
    }
  };

  // 🔥 Add Question
  const addQuestion = async () => {
    try {
      await axios.post("http://127.0.0.1:8000/add-question", {
        quiz_id: quizId,
        question: question,
        ...options,
        correct_answer: correct
      });

      alert("Question Added!");

      // reset
      setQuestion("");
      setOptions({
        option1: "",
        option2: "",
        option3: "",
        option4: ""
      });
      setCorrect("");

    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      <h2 style={{ color: "#6a1b9a" }}>Create Quiz 🎓</h2>

      {/* Course Select */}
      <select onChange={(e) => setCourseId(e.target.value)} style={input}>
        <option value="">Select Course</option>
        {courses.map(c => (
          <option key={c.id} value={c.id}>
            {c.title}
          </option>
        ))}
      </select>

      <input
        placeholder="Quiz Title"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        style={input}
      />

      <button onClick={createQuiz} style={btn}>
        Create Quiz
      </button>

      {/* Add Question */}
      {quizId && (
        <div style={card}>
          <h3>Add Question</h3>

          <input
            placeholder="Question"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            style={input}
          />

          {["option1", "option2", "option3", "option4"].map((opt) => (
            <input
              key={opt}
              placeholder={opt}
              value={options[opt]}
              onChange={(e) =>
                setOptions({ ...options, [opt]: e.target.value })
              }
              style={input}
            />
          ))}

          <input
            placeholder="Correct Answer"
            value={correct}
            onChange={(e) => setCorrect(e.target.value)}
            style={input}
          />

          <button onClick={addQuestion} style={btn}>
            Add Question
          </button>
        </div>
      )}
    </div>
  );
}

/* Styles */
const input = {
  display: "block",
  marginBottom: "10px",
  padding: "10px",
  borderRadius: "8px",
  width: "100%"
};

const btn = {
  background: "#7b1fa2",
  color: "#fff",
  padding: "10px",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  marginBottom: "15px"
};

const card = {
  background: "#fff",
  padding: "15px",
  borderRadius: "10px",
  boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
};

export default QuizTeacher;
